def annuity_rate(present_value=None, payment=None, periods=None, timing=None):
    """Interest rate of an annuity. The rate per period at which n equal payments are worth a given present value (bisection; the rate is unique because the present value falls as the rate rises).
    Formula: PV = PMT\\,\\frac{1 - (1+r)^{-n}}{r}
    Inputs:
        present_value: present value (amount borrowed or price paid)
        payment: payment per period
        periods: number of payments
        timing: 'ordinary' (end of each period, default) or 'due' (beginning) (optional)
    Outputs: rate (interest rate per period)
    See also: help("annuity_rate")
    """
    given = {k: v for k, v in dict(present_value=present_value, payment=payment, periods=periods, timing=timing).items() if v is not None}
    return _P.solve("annuity_rate", **given)

