def bond_ytm(price=None, face=None, coupon_rate=None, years=None, frequency=None):
    """Yield to maturity of a bond. The yield to maturity (nominal annual, compounded at the coupon frequency) that equates the bond's price to the present value of its coupons and face value.
    Formula: \\text{price} = \\sum_{k=1}^{N} \\frac{C}{(1 + y/m)^{k}} + \\frac{F}{(1 + y/m)^{N}}
    Inputs:
        price: bond price (clean = dirty on a coupon date)
        face: face (par) value repaid at maturity
        coupon_rate: annual coupon rate (decimal)
        years: years to maturity (a whole number of coupon periods)
        frequency: coupons per year (2 = semiannual, default) (optional)
    Outputs: ytm (yield to maturity, nominal annual), current_yield (annual coupon / price)
    See also: help("bond_ytm")
    """
    given = {k: v for k, v in dict(price=price, face=face, coupon_rate=coupon_rate, years=years, frequency=frequency).items() if v is not None}
    return _P.solve("bond_ytm", **given)

def break_even(fixed_costs=None, price=None, variable_cost=None, target_profit=None):
    """Break-even and target-profit volume. Units to sell to cover fixed costs (and reach a target profit): Q = (F + target) / (p - v).
    Formula: Q_{BE} = \\frac{F + \\pi_{target}}{p - v}
    Inputs:
        fixed_costs: total fixed costs
        price: selling price per unit
        variable_cost: variable cost per unit
        target_profit: target profit (default 0: break-even) (optional)
    Outputs: quantity (units (F + target)/(p - v)), revenue (p Q), contribution_margin (p - v per unit), contribution_margin_ratio ((p - v)/p)
    See also: help("break_even")
    """
    given = {k: v for k, v in dict(fixed_costs=fixed_costs, price=price, variable_cost=variable_cost, target_profit=target_profit).items() if v is not None}
    return _P.solve("break_even", **given)

def bs_greeks(spot=None, strike=None, time=None, rate=None, volatility=None, dividend_yield=None):
    """Black-Scholes Greeks. Delta, gamma, vega, theta and rho of European calls and puts (Black-Scholes-Merton, continuous dividend yield). Vega per 1.00 of volatility, theta per year, rho per 1.00 of rate.
    Formula: \\Delta_C = e^{-qT}N(d_1),\\ \\Gamma = \\frac{e^{-qT}\\varphi(d_1)}{S\\sigma\\sqrt{T}},\\ \\nu = S e^{-qT}\\varphi(d_1)\\sqrt{T}
    Inputs:
        spot: price of the underlying now
        strike: strike (exercise) price
        time: time to expiry in years
        rate: risk-free rate, continuously compounded (decimal)
        volatility: volatility of the underlying, annual (decimal)
        dividend_yield: continuous dividend yield (decimal, default 0) (optional)
    Outputs: call_delta (dC/dS), put_delta (dP/dS), gamma (d2V/dS2 (call = put)), vega (dV/dsigma (call = put)), call_theta (-dC/dT per year), put_theta (-dP/dT per year), call_rho (dC/dr), put_rho (dP/dr)
    See also: help("bs_greeks")
    """
    given = {k: v for k, v in dict(spot=spot, strike=strike, time=time, rate=rate, volatility=volatility, dividend_yield=dividend_yield).items() if v is not None}
