def cagr(begin_value=None, end_value=None, years=None):
    """Compound annual growth rate. The constant annual growth rate that takes a beginning value to an ending value over a number of years.
    Formula: \\mathrm{CAGR} = \\left(\\frac{V_{end}}{V_{begin}}\\right)^{1/t} - 1
    Inputs:
        begin_value: value at the start
        end_value: value at the end
        years: number of years
    Outputs: cagr (compound annual growth rate (end/begin)^(1/t) - 1), total_growth (end/begin - 1)
    See also: help("cagr")
    """
    given = {k: v for k, v in dict(begin_value=begin_value, end_value=end_value, years=years).items() if v is not None}
    return _P.solve("cagr", **given)

def capm(risk_free=None, beta=None, market_return=None):
    """Capital asset pricing model. Expected return of an asset from its beta: E[R] = rf + beta (E[Rm] - rf) (the security market line).
    Formula: E[R_i] = r_f + \\beta_i\\,(E[R_m] - r_f)
    Inputs:
        risk_free: risk-free rate (decimal)
        beta: beta of the asset
        market_return: expected market return (decimal)
    Outputs: expected_return (expected (required) return), market_risk_premium (rm - rf), risk_premium (beta (rm - rf))
    See also: help("capm")
    """
    given = {k: v for k, v in dict(risk_free=risk_free, beta=beta, market_return=market_return).items() if v is not None}
    return _P.solve("capm", **given)

def cobb_douglas_demand(alpha=None, beta=None, income=None, price_x=None, price_y=None):
    """Utility-maximising demand (Cobb-Douglas). The bundle that maximises U = x^alpha y^beta subject to px x + py y = M.
    Formula: x^{*} = \\frac{\\alpha}{\\alpha+\\beta}\\frac{M}{p_x},\\quad y^{*} = \\frac{\\beta}{\\alpha+\\beta}\\frac{M}{p_y}
    Inputs:
        alpha: exponent of good x
        beta: exponent of good y
        income: income (budget)
        price_x: price of good x
        price_y: price of good y
    Outputs: x (alpha/(alpha+beta) M/px), y (beta/(alpha+beta) M/py), utility (x^alpha y^beta), share_x (budget share of x)
    See also: help("cobb_douglas_demand")
    """
    given = {k: v for k, v in dict(alpha=alpha, beta=beta, income=income, price_x=price_x, price_y=price_y).items() if v is not None}
    return _P.solve("cobb_douglas_demand", **given)

def compound_interest(principal=None, rate=None, years=None, periods_per_year=None):
    """Compound interest. Future amount of a sum invested at a nominal annual rate compounded m times a year: A = P (1 + r/m)^(m t).
    Formula: A = P\\left(1 + \\frac{r}{m}\\right)^{m t}
    Inputs:
        principal: amount invested now
        rate: nominal annual interest rate (decimal; 5% = 0.05)
        years: time in years
        periods_per_year: compounding periods per year (1 annual, 12 monthly, 365 daily) (optional)
    Outputs: amount (future amount A), interest (compound interest earned A - P)
    See also: help("compound_interest")
    """
    given = {k: v for k, v in dict(principal=principal, rate=rate, years=years, periods_per_year=periods_per_year).items() if v is not None}
    return _P.solve("compound_interest", **given)

def continuous_compounding(principal=None, rate=None, years=None):
    """Continuous compounding. Future amount of a sum growing at a continuously compounded annual rate: A = P e^(r t).
    Formula: A = P e^{r t}
    Inputs:
        principal: amount invested now
        rate: continuously compounded annual rate (decimal)
        years: time in years
    Outputs: amount (future amount P e^(r t)), interest (interest earned)
    See also: help("continuous_compounding")
    """
    given = {k: v for k, v in dict(principal=principal, rate=rate, years=years).items() if v is not None}
    return _P.solve("continuous_compounding", **given)

def correlation(x=None, y=None):
    """Correlation and covariance of two series. Pearson correlation and sample covariance (n - 1) of two paired series, such as the returns of two assets.
    Formula: r = \\frac{\\sum (x - \\bar x)(y - \\bar y)}{\\sqrt{\\sum (x-\\bar x)^{2}\\sum (y-\\bar y)^{2}}}
    Inputs:
        x: first series
        y: second series
    Outputs: correlation (Pearson r), covariance (sample covariance), r_squared (r^2)
    See also: help("correlation")
    """
    given = {k: v for k, v in dict(x=x, y=y).items() if v is not None}
    return _P.solve("correlation", **given)

def cournot(price_intercept=None, price_slope=None, cost_1=None, cost_2=None):
    """Cournot duopoly equilibrium. Quantities, price and profits of two firms choosing quantities simultaneously against P = A - B(q1 + q2) with constant marginal costs.
    Formula: q_i^{*} = \\frac{A - 2c_i + c_j}{3B}
    Inputs:
        price_intercept: A in the inverse demand P = A - B Q
        price_slope: B in P = A - B Q (B > 0)
        cost_1: marginal cost of firm 1
        cost_2: marginal cost of firm 2
    Outputs: q1 ((A - 2c1 + c2)/(3B)), q2 ((A - 2c2 + c1)/(3B)), price (A - B(q1 + q2)), profit_1 ((P - c1) q1), profit_2 ((P - c2) q2)
    See also: help("cournot")
    """
    given = {k: v for k, v in dict(price_intercept=price_intercept, price_slope=price_slope, cost_1=cost_1, cost_2=cost_2).items() if v is not None}
    return _P.solve("cournot", **given)

def cross_price_elasticity(price_other_1=None, quantity_1=None, price_other_2=None, quantity_2=None):
    """Cross-price elasticity of demand (midpoint). Midpoint cross-price elasticity: response of the quantity of good A to the price of good B; positive = substitutes, negative = complements.
    Formula: E_{AB} = \\frac{\\Delta Q_A/\\bar Q_A}{\\Delta P_B/\\bar P_B}
    Inputs:
        price_other_1: first price of the other good
        quantity_1: quantity of this good at that price
        price_other_2: second price of the other good
        quantity_2: quantity of this good at the second price
    Outputs: elasticity ((dQa / mean Qa) / (dPb / mean Pb)), relationship (substitutes, complements or independent)
    See also: help("cross_price_elasticity")
    """
    given = {k: v for k, v in dict(price_other_1=price_other_1, quantity_1=quantity_1, price_other_2=price_other_2, quantity_2=quantity_2).items() if v is not None}
    return _P.solve("cross_price_elasticity", **given)

def crossover_rate(cash_flows_a=None, cash_flows_b=None):
    """NPV crossover rate of two projects. The discount rate at which two projects have equal NPV (the IRR of the difference A - B); given only when it is unique.
    Formula: \\sum_t \\frac{CF^A_t - CF^B_t}{(1 + r^{*})^{t}} = 0
    Inputs:
        cash_flows_a: cash flows of project A [CF0, ..., CFn]
        cash_flows_b: cash flows of project B, same periods
    Outputs: crossover_rate (rate at which NPV(A) = NPV(B)), npv_at_crossover (the common NPV at that rate)
    See also: help("crossover_rate")
    """
    given = {k: v for k, v in dict(cash_flows_a=cash_flows_a, cash_flows_b=cash_flows_b).items() if v is not None}
    return _P.solve("crossover_rate", **given)

def discounted_payback(rate=None, cash_flows=None):
    """Discounted payback period. Time until the cumulative DISCOUNTED cash flow turns non-negative (linear within the period).
    Formula: \\sum_{s \\le t} \\frac{CF_s}{(1+r)^{s}} \\ge 0
    Inputs:
        rate: discount rate per period (decimal)
        cash_flows: cash flows [CF0 < 0, CF1, ..., CFn > 0]
    Outputs: discounted_payback (discounted payback period in periods)
    See also: help("discounted_payback")
    """
    given = {k: v for k, v in dict(rate=rate, cash_flows=cash_flows).items() if v is not None}
    return _P.solve("discounted_payback", **given)

def doubling_time(rate=None):
    """Doubling time. How many periods an amount compounding at r per period takes to double, with the rule-of-72 estimate.
    Formula: n = \\frac{\\ln 2}{\\ln(1 + r)}
    Inputs:
        rate: interest or growth rate per period (decimal)
    Outputs: periods (exact doubling time ln 2 / ln(1 + r)), rule_of_72 (rule-of-72 estimate 72 / (100 r))
    See also: help("doubling_time")
    """
    given = {k: v for k, v in dict(rate=rate).items() if v is not None}
    return _P.solve("doubling_time", **given)

def durbin_watson(residuals=None):
    """Durbin-Watson statistic. Durbin-Watson statistic of regression residuals in time order (about 2: no first-order autocorrelation; toward 0: positive; toward 4: negative).
    Formula: DW = \\frac{\\sum_{t=2}^{n}(e_t - e_{t-1})^{2}}{\\sum_{t=1}^{n} e_t^{2}}
    Inputs:
        residuals: regression residuals in time order
    Outputs: durbin_watson (sum (e_t - e_t-1)^2 / sum e_t^2)
    See also: help("durbin_watson")
    """
    given = {k: v for k, v in dict(residuals=residuals).items() if v is not None}
    return _P.solve("durbin_watson", **given)

def effective_annual_rate(rate=None, periods_per_year=None):
    """Effective annual rate. The effective annual rate (annual percentage yield) of a nominal rate compounded m times a year.
    Formula: \\mathrm{EAR} = \\left(1 + \\frac{r}{m}\\right)^{m} - 1
    Inputs:
        rate: nominal annual rate (decimal)
        periods_per_year: compounding periods per year
    Outputs: effective_rate (effective annual rate (1 + r/m)^m - 1), periodic_rate (rate per period r/m)
    See also: help("effective_annual_rate")
    """
    given = {k: v for k, v in dict(rate=rate, periods_per_year=periods_per_year).items() if v is not None}
    return _P.solve("effective_annual_rate", **given)

def endowment_insurance(mortality_rates=None, interest_rate=None, term=None, benefit=None):
    """Endowment insurance. Actuarial present value of a benefit paid at the end of the year of death within n years, or at year n if alive then (term insurance + pure endowment).
    Formula: A_{x:\\overline{n}|} = A^{1}_{x:\\overline{n}|} + v^{n}\\,{}_{n}p_x
    Inputs:
        mortality_rates: one-year death probabilities q_x, q_x+1, ... from the current age
        interest_rate: annual effective interest rate (decimal)
        term: term n in years
        benefit: benefit amount (default 1) (optional)
    Outputs: apv (B (A^1_{x:n} + nE_x)), term_part (B A^1_{x:n}), pure_endowment (B v^n n p_x)
    See also: help("endowment_insurance")
    """
    given = {k: v for k, v in dict(mortality_rates=mortality_rates, interest_rate=interest_rate, term=term, benefit=benefit).items() if v is not None}
    return _P.solve("endowment_insurance", **given)

def equivalent_annual_annuity(rate=None, cash_flows=None):
    """Equivalent annual annuity. The level payment over the project's life with the same NPV (for comparing projects of unequal lives).
    Formula: EAA = \\frac{NPV\\,r}{1 - (1 + r)^{-n}}
    Inputs:
        rate: discount rate per period (decimal)
        cash_flows: cash flows [CF0, CF1, ..., CFn]
    Outputs: eaa (equivalent annual annuity NPV r / (1 - (1 + r)^-n)), npv (net present value)
    See also: help("equivalent_annual_annuity")
    """
    given = {k: v for k, v in dict(rate=rate, cash_flows=cash_flows).items() if v is not None}
    return _P.solve("equivalent_annual_annuity", **given)

def fisher_real_rate(nominal_rate=None, inflation_rate=None):
    """Real interest rate (Fisher equation). The exact real rate (1 + i)/(1 + pi) - 1 and the approximation i - pi.
    Formula: 1 + i = (1 + r)(1 + \\pi)
    Inputs:
        nominal_rate: nominal interest rate (decimal)
        inflation_rate: inflation rate (decimal)
    Outputs: real_rate ((1 + i)/(1 + pi) - 1), approximate_real_rate (i - pi)
    See also: help("fisher_real_rate")
    """
    given = {k: v for k, v in dict(nominal_rate=nominal_rate, inflation_rate=inflation_rate).items() if v is not None}
    return _P.solve("fisher_real_rate", **given)

def forward_price(spot=None, rate=None, time=None, dividend_yield=None, storage_cost=None):
    """Forward price with cost of carry. No-arbitrage forward price of an asset with a continuous income yield q and storage cost u: S e^((r + u - q) T).
    Formula: F_0 = S_0\\,e^{(r + u - q)T}
    Inputs:
        spot: spot price now
        rate: risk-free rate, continuously compounded (decimal)
        time: time to delivery in years
        dividend_yield: continuous income or convenience yield (decimal, default 0) (optional)
        storage_cost: continuous storage cost rate (decimal, default 0) (optional)
    Outputs: forward (forward price), cost_of_carry (r + u - q)
    See also: help("forward_price")
    """
    given = {k: v for k, v in dict(spot=spot, rate=rate, time=time, dividend_yield=dividend_yield, storage_cost=storage_cost).items() if v is not None}
    return _P.solve("forward_price", **given)

def forward_price_dividends(spot=None, rate=None, time=None, dividends=None, dividend_times=None):
    """Forward price with known dividends. Forward price of a stock paying known cash dividends before delivery: F = (S - PV(dividends)) e^(rT).
    Formula: F_0 = \\left(S_0 - \\sum_i D_i e^{-r t_i}\\right)e^{rT}
    Inputs:
        spot: stock price now
        rate: risk-free rate, continuously compounded (decimal)
        time: time to delivery in years
        dividends: cash dividends (list)
        dividend_times: time of each dividend in years (list)
    Outputs: forward (forward price), pv_dividends (present value of the dividends)
    See also: help("forward_price_dividends")
    """
    given = {k: v for k, v in dict(spot=spot, rate=rate, time=time, dividends=dividends, dividend_times=dividend_times).items() if v is not None}
    return _P.solve("forward_price_dividends", **given)

def forward_rate(spot_rate_1=None, maturity_1=None, spot_rate_2=None, maturity_2=None):
    """Implied forward rate from spot rates. The annually compounded forward rate between t1 and t2 implied by the spot rates for t1 and t2.
    Formula: f_{t_1,t_2} = \\left[\\frac{(1+s_2)^{t_2}}{(1+s_1)^{t_1}}\\right]^{1/(t_2 - t_1)} - 1
    Inputs:
        spot_rate_1: spot rate to maturity t1 (annual compounding)
        maturity_1: first maturity t1 in years
        spot_rate_2: spot rate to maturity t2 (annual compounding)
        maturity_2: second maturity t2 > t1 in years
    Outputs: forward_rate (forward rate f(t1, t2), annual compounding)
    See also: help("forward_rate")
    """
    given = {k: v for k, v in dict(spot_rate_1=spot_rate_1, maturity_1=maturity_1, spot_rate_2=spot_rate_2, maturity_2=maturity_2).items() if v is not None}
    return _P.solve("forward_rate", **given)

def future_value_annuity(payment=None, rate=None, periods=None, timing=None):
    """Future value of an annuity. The accumulated value after n periods of equal payments, ordinary (end of period) or due (beginning).
    Formula: FV = PMT\\,\\frac{(1+r)^{n} - 1}{r}\\;(\\times (1 + r)\\ \\text{if due})
    Inputs:
        payment: payment per period
        rate: interest rate per period (decimal)
        periods: number of payments
        timing: 'ordinary' (end of each period, default) or 'due' (beginning) (optional)
    Outputs: future_value (accumulated value at the end of period n)
    See also: help("future_value_annuity")
    """
    given = {k: v for k, v in dict(payment=payment, rate=rate, periods=periods, timing=timing).items() if v is not None}
    return _P.solve("future_value_annuity", **given)

def gdp_deflator(base_prices=None, base_quantities=None, current_prices=None, current_quantities=None):
    """Nominal GDP, real GDP and the GDP deflator. Nominal GDP (current prices), real GDP (base-year prices), the GDP deflator, inflation since the base year and real growth, from the prices and quantities of the goods produced.
    Formula: \\text{Deflator} = 100\\,\\frac{\\sum p_1 q_1}{\\sum p_0 q_1}
    Inputs:
        base_prices: prices in the base year
        base_quantities: quantities in the base year
        current_prices: prices in the current year
        current_quantities: quantities in the current year
    Outputs: nominal_gdp (sum p1 q1), real_gdp (sum p0 q1), deflator (100 x nominal / real), inflation (deflator/100 - 1 (since the base year)), real_growth (real GDP / base-year GDP - 1)
    See also: help("gdp_deflator")
    """
    given = {k: v for k, v in dict(base_prices=base_prices, base_quantities=base_quantities, current_prices=current_prices, current_quantities=current_quantities).items() if v is not None}
    return _P.solve("gdp_deflator", **given)

def gini_coefficient(incomes=None):
    """Gini coefficient. Gini coefficient of a list of incomes (population formula: mean absolute difference / twice the mean; 0 = equality, (n-1)/n = one person has everything).
    Formula: G = \\frac{\\sum_i \\sum_j |x_i - x_j|}{2 n^{2} \\bar x}
    Inputs:
        incomes: incomes (or wealth) of the people or households
    Outputs: gini (sum (2i - n - 1) x_(i) / (n sum x))
    See also: help("gini_coefficient")
    """
    given = {k: v for k, v in dict(incomes=incomes).items() if v is not None}
    return _P.solve("gini_coefficient", **given)

def global_min_variance(covariance=None):
    """Global minimum-variance portfolio. Weights (adding up to 1, short sales allowed) of the portfolio with the smallest variance, from a covariance matrix: w = Sigma^-1 1 / (1' Sigma^-1 1).
    Formula: w^{*} = \\frac{\\Sigma^{-1}\\mathbf{1}}{\\mathbf{1}^{\\top}\\Sigma^{-1}\\mathbf{1}}
    Inputs:
        covariance: covariance matrix of the asset returns
    Outputs: weights (minimum-variance weights (list)), variance (portfolio variance), std_dev (portfolio sd)
    See also: help("global_min_variance")
    """
    given = {k: v for k, v in dict(covariance=covariance).items() if v is not None}
    return _P.solve("global_min_variance", **given)

def gordon_growth(required_return=None, growth=None, dividend=None, next_dividend=None):
    """Dividend discount model (Gordon growth). Value of a share whose dividend grows at a constant rate forever: P0 = D1 / (r - g).
    Formula: P_0 = \\frac{D_1}{r - g} = \\frac{D_0 (1 + g)}{r - g}
    Inputs:
        required_return: required return on equity (decimal)
        growth: constant dividend growth rate (decimal)
        dividend: dividend just paid D0 (give this OR next_dividend) (optional)
        next_dividend: dividend expected one year from now D1 (give this OR dividend) (optional)
    Outputs: price (share value P0 = D1 / (r - g)), next_dividend (D1 = D0 (1 + g)), dividend_yield (D1 / P0 = r - g)
    See also: help("gordon_growth")
    """
    given = {k: v for k, v in dict(required_return=required_return, growth=growth, dividend=dividend, next_dividend=next_dividend).items() if v is not None}
    return _P.solve("gordon_growth", **given)

def gordon_implied_return(price=None, growth=None, dividend=None, next_dividend=None):
    """Required return implied by the Gordon model. The return investors require given a share price and a constant dividend growth rate: r = D1 / P0 + g.
    Formula: r = \\frac{D_1}{P_0} + g
    Inputs:
        price: current share price
        growth: constant dividend growth rate (decimal)
        dividend: dividend just paid D0 (give this OR next_dividend) (optional)
        next_dividend: dividend expected one year from now D1 (give this OR dividend) (optional)
    Outputs: required_return (implied required return D1/P0 + g), dividend_yield (D1 / P0), next_dividend (D1)
    See also: help("gordon_implied_return")
    """
    given = {k: v for k, v in dict(price=price, growth=growth, dividend=dividend, next_dividend=next_dividend).items() if v is not None}
    return _P.solve("gordon_implied_return", **given)

def growing_annuity(first_payment=None, rate=None, growth=None, periods=None):
    """Present and future value of a growing annuity. n payments at the end of each period, the first C1, each growing at g per period.
    Formula: PV = \\frac{C_1}{r - g}\\left[1 - \\left(\\frac{1+g}{1+r}\\right)^{n}\\right]
    Inputs:
        first_payment: first payment (end of period 1)
        rate: discount rate per period (decimal)
        growth: growth rate per period (decimal)
        periods: number of payments
    Outputs: present_value (value today), future_value (value at the end of period n)
    See also: help("growing_annuity")
    """
    given = {k: v for k, v in dict(first_payment=first_payment, rate=rate, growth=growth, periods=periods).items() if v is not None}
    return _P.solve("growing_annuity", **given)

def growing_perpetuity(first_payment=None, rate=None, growth=None):
    """Present value of a growing perpetuity. The value today of payments that start at C one period from now and grow at g per period forever: C / (r - g).
    Formula: PV = \\frac{C_1}{r - g}
    Inputs:
        first_payment: payment one period from now
        rate: discount rate per period (decimal)
        growth: growth rate per period (decimal)
    Outputs: present_value (value today C1 / (r - g))
    See also: help("growing_perpetuity")
    """
    given = {k: v for k, v in dict(first_payment=first_payment, rate=rate, growth=growth).items() if v is not None}
    return _P.solve("growing_perpetuity", **given)

def herfindahl_index(market_shares=None):
    """Herfindahl-Hirschman index and concentration ratio. Market concentration from the firms' shares or sales (normalized to shares): HHI on the 0-10,000 scale, the four-firm concentration ratio and the equivalent number of equal-sized firms.
    Formula: HHI = 10\\,000\\sum_i s_i^{2}
    Inputs:
        market_shares: market shares (in %) or sales of each firm
    Outputs: hhi (10,000 x sum of squared shares), hhi_fraction (sum of squared shares (0-1)), cr4 (combined share of the four largest firms, %), equivalent_firms (1 / HHI (fraction))
    See also: help("herfindahl_index")
    """
    given = {k: v for k, v in dict(market_shares=market_shares).items() if v is not None}
    return _P.solve("herfindahl_index", **given)

def historical_var(returns=None, confidence=None, portfolio_value=None):
    """Historical value at risk and expected shortfall. VaR and CVaR (expected shortfall) by historical simulation: with k = ceil(n (1 - confidence)), VaR is minus the k-th smallest return and CVaR minus the mean of the k smallest, times the portfolio value.
    Formula: \\mathrm{VaR}_c = -R_{(k)},\\quad \\mathrm{CVaR}_c = -\\frac{1}{k}\\sum_{i=1}^{k} R_{(i)},\\quad k = \\lceil n(1-c)\\rceil
    Inputs:
        returns: historical returns (decimals)
        confidence: confidence level (0.95 = 95%)
        portfolio_value: portfolio value (default 1: VaR as a fraction) (optional)
    Outputs: var (value at risk (a positive number is a loss)), cvar (expected shortfall (mean loss beyond VaR)), tail_observations (k, the number of returns in the tail)
    See also: help("historical_var")
    """
    given = {k: v for k, v in dict(returns=returns, confidence=confidence, portfolio_value=portfolio_value).items() if v is not None}
    return _P.solve("historical_var", **given)

def implied_volatility(option_price=None, spot=None, strike=None, time=None, rate=None, dividend_yield=None, option_type=None):
    """Implied volatility. The volatility at which the Black-Scholes price of a European call or put equals its market price.
    Formula: C_{BS}(\\sigma_{imp}) = C_{market}
    Inputs:
        option_price: market price of the option
        spot: price of the underlying now
        strike: strike (exercise) price
        time: time to expiry in years
        rate: risk-free rate, continuously compounded (decimal)
        dividend_yield: continuous dividend yield (decimal, default 0) (optional)
        option_type: call (default) or put (optional)
    Outputs: volatility (implied volatility, annual), vega (vega at that volatility)
    See also: help("implied_volatility")
    """
    given = {k: v for k, v in dict(option_price=option_price, spot=spot, strike=strike, time=time, rate=rate, dividend_yield=dividend_yield, option_type=option_type).items() if v is not None}
    return _P.solve("implied_volatility", **given)

def income_elasticity(income_1=None, quantity_1=None, income_2=None, quantity_2=None):
    """Income elasticity of demand (midpoint). Midpoint income elasticity of demand and the good's type (inferior, necessity, luxury).
    Formula: E_I = \\frac{(Q_2 - Q_1)/\\bar Q}{(I_2 - I_1)/\\bar I}
    Inputs:
        income_1: first income
        quantity_1: quantity at income 1
        income_2: second income
        quantity_2: quantity at income 2
    Outputs: elasticity ((dQ / mean Q) / (dI / mean I)), classification (inferior, necessity or luxury)
    See also: help("income_elasticity")
    """
    given = {k: v for k, v in dict(income_1=income_1, quantity_1=quantity_1, income_2=income_2, quantity_2=quantity_2).items() if v is not None}
    return _P.solve("income_elasticity", **given)

def inflation_adjustment(price_levels=None, amount=None):
    """Inflation from a price index series. Total and average annual (geometric) inflation from consecutive price levels (CPI), and the value of an amount in the last period's money expressed in first-period money.
    Formula: \\bar\\pi = \\left(\\frac{P_n}{P_0}\\right)^{1/n} - 1
    Inputs:
        price_levels: price index levels in consecutive periods (e.g. CPI each year)
        amount: an amount in last-period money to deflate (optional) (optional)
    Outputs: total_inflation (P_last / P_first - 1), average_inflation ((P_last/P_first)^(1/n) - 1), real_value (amount x P_first / P_last)
    See also: help("inflation_adjustment")
    """
    given = {k: v for k, v in dict(price_levels=price_levels, amount=amount).items() if v is not None}
    return _P.solve("inflation_adjustment", **given)

def information_ratio(portfolio_returns=None, benchmark_returns=None):
    """Information ratio and tracking error. Mean active return (portfolio - benchmark) per unit of tracking error (sample sd of active returns).
    Formula: IR = \\frac{\\overline{R_p - R_b}}{s(R_p - R_b)}
    Inputs:
        portfolio_returns: portfolio returns (decimals)
        benchmark_returns: benchmark returns in the same periods
    Outputs: information_ratio (mean active / tracking error), tracking_error (sample sd of active returns), mean_active_return (mean of portfolio - benchmark)
    See also: help("information_ratio")
    """
    given = {k: v for k, v in dict(portfolio_returns=portfolio_returns, benchmark_returns=benchmark_returns).items() if v is not None}
    return _P.solve("information_ratio", **given)

def irr(cash_flows=None):
    """Internal rate of return. The discount rate at which the NPV of [CF0, ..., CFn] is zero; given only when it is unique (the cash flows change sign exactly once).
    Formula: \\sum_{t=0}^{n} \\frac{CF_t}{(1 + \\mathrm{IRR})^{t}} = 0
    Inputs:
        cash_flows: cash flows [CF0, CF1, ..., CFn], CF0 at time 0
    Outputs: irr (internal rate of return per period)
    See also: help("irr")
    """
    given = {k: v for k, v in dict(cash_flows=cash_flows).items() if v is not None}
    return _P.solve("irr", **given)

def life_annuity_due(mortality_rates=None, interest_rate=None, payment=None):
    """Whole life annuity-due. Actuarial present value of a payment at the start of every year while the person is alive.
    Formula: \\ddot a_x = \\sum_{k=0}^{\\infty} v^{k}\\,{}_{k}p_x
    Inputs:
        mortality_rates: one-year death probabilities q_x, q_x+1, ... from the current age
        interest_rate: annual effective interest rate (decimal)
        payment: annual payment (default 1) (optional)
    Outputs: apv (P a-due_x = P sum v^k k p_x)
    See also: help("life_annuity_due")
    """
    given = {k: v for k, v in dict(mortality_rates=mortality_rates, interest_rate=interest_rate, payment=payment).items() if v is not None}
    return _P.solve("life_annuity_due", **given)

def life_expectancy(mortality_rates=None):
    """Life expectancy from a life table. Curtate expectation of life e_x = sum_{k>=1} k p_x (whole years lived) and the complete expectation e_x + 1/2 (deaths uniform within each year).
    Formula: e_x = \\sum_{k=1}^{\\infty} {}_{k}p_x
    Inputs:
        mortality_rates: one-year death probabilities q_x, q_x+1, ... from the current age
    Outputs: curtate (curtate expectation of life e_x), complete (complete expectation e_x + 0.5 (UDD))
    See also: help("life_expectancy")
    """
    given = {k: v for k, v in dict(mortality_rates=mortality_rates).items() if v is not None}
    return _P.solve("life_expectancy", **given)

def loan_balance(principal=None, annual_rate=None, years=None, payments_made=None, payments_per_year=None):
    """Remaining balance of a loan. The balance still owed on an amortizing loan after k level payments.
    Formula: B_k = P(1+i)^{k} - PMT\\,\\frac{(1+i)^{k} - 1}{i}
    Inputs:
        principal: amount borrowed
        annual_rate: nominal annual interest rate (decimal), compounded at the payment frequency
        years: term of the loan in years
        payments_made: number of payments already made
        payments_per_year: payments per year (12 = monthly, default) (optional)
    Outputs: balance (balance owed after k payments), payment (level payment per period)
    See also: help("loan_balance")
    """
    given = {k: v for k, v in dict(principal=principal, annual_rate=annual_rate, years=years, payments_made=payments_made, payments_per_year=payments_per_year).items() if v is not None}
    return _P.solve("loan_balance", **given)

def loan_cumulative_interest(principal=None, annual_rate=None, years=None, payments_made=None, payments_per_year=None):
    """Cumulative interest of a loan. Total interest paid and principal repaid over the first k payments of an amortizing loan.
    Formula: \\sum_{j=1}^{k} I_j = k\\,PMT - (P - B_k)
    Inputs:
        principal: amount borrowed
        annual_rate: nominal annual interest rate (decimal), compounded at the payment frequency
        years: term of the loan in years
        payments_made: number of payments counted (the first k)
        payments_per_year: payments per year (12 = monthly, default) (optional)
    Outputs: cumulative_interest (interest paid in payments 1..k), principal_repaid (principal repaid in payments 1..k)
    See also: help("loan_cumulative_interest")
    """
    given = {k: v for k, v in dict(principal=principal, annual_rate=annual_rate, years=years, payments_made=payments_made, payments_per_year=payments_per_year).items() if v is not None}
    return _P.solve("loan_cumulative_interest", **given)

def loan_payment(principal=None, annual_rate=None, years=None, payments_per_year=None):
    """Loan payment (amortizing loan). The level payment that repays a loan over its term, with the total paid and the total interest.
    Formula: PMT = \\frac{P\\,i}{1 - (1+i)^{-n}}
    Inputs:
        principal: amount borrowed
        annual_rate: nominal annual interest rate (decimal), compounded at the payment frequency
        years: term of the loan in years
        payments_per_year: payments per year (12 = monthly, default) (optional)
    Outputs: payment (level payment per period), number_of_payments (number of payments n = years x m), total_paid (payment x n), total_interest (total paid - principal)
    See also: help("loan_payment")
    """
    given = {k: v for k, v in dict(principal=principal, annual_rate=annual_rate, years=years, payments_per_year=payments_per_year).items() if v is not None}
    return _P.solve("loan_payment", **given)

def loan_payment_split(principal=None, annual_rate=None, years=None, payment_number=None, payments_per_year=None):
    """Interest and principal in a loan payment. How payment number k of an amortizing loan splits into interest and principal repayment.
    Formula: I_k = i\\,B_{k-1},\\quad P_k = PMT - I_k
    Inputs:
        principal: amount borrowed
        annual_rate: nominal annual interest rate (decimal), compounded at the payment frequency
        years: term of the loan in years
        payment_number: which payment (1 = the first)
        payments_per_year: payments per year (12 = monthly, default) (optional)
    Outputs: interest_part (interest in payment k), principal_part (principal repaid by payment k), payment (level payment)
    See also: help("loan_payment_split")
    """
    given = {k: v for k, v in dict(principal=principal, annual_rate=annual_rate, years=years, payment_number=payment_number, payments_per_year=payments_per_year).items() if v is not None}
    return _P.solve("loan_payment_split", **given)

def log_log_elasticity(prices=None, quantities=None):
    """Constant elasticity from a log-log regression. The price elasticity estimated as the slope of ln Q on ln P (constant-elasticity demand Q = A P^e).
    Formula: \\ln Q = \\ln A + \\varepsilon \\ln P
    Inputs:
        prices: observed prices
        quantities: quantities at those prices
    Outputs: elasticity (slope of ln Q on ln P), intercept (ln A), r_squared (R^2 of the log-log fit)
    See also: help("log_log_elasticity")
    """
    given = {k: v for k, v in dict(prices=prices, quantities=quantities).items() if v is not None}
    return _P.solve("log_log_elasticity", **given)

def market_equilibrium(demand_intercept=None, demand_slope=None, supply_intercept=None, supply_slope=None):
    """Market equilibrium and surplus (linear curves). Equilibrium price and quantity of Qd = a - bP and Qs = c + dP, with consumer, producer and total surplus (producer surplus counted at prices >= 0).
    Formula: P^{*} = \\frac{a - c}{b + d},\\quad CS = \\frac{Q^{*2}}{2b}
    Inputs:
        demand_intercept: a in Qd = a - bP
        demand_slope: b in Qd = a - bP (b > 0)
        supply_intercept: c in Qs = c + dP
        supply_slope: d in Qs = c + dP (d > 0)
    Outputs: price (equilibrium price (a - c)/(b + d)), quantity (equilibrium quantity), consumer_surplus (Q^2 / (2b)), producer_surplus (area above supply, below P), total_surplus (CS + PS)
    See also: help("market_equilibrium")
    """
    given = {k: v for k, v in dict(demand_intercept=demand_intercept, demand_slope=demand_slope, supply_intercept=supply_intercept, supply_slope=supply_slope).items() if v is not None}
    return _P.solve("market_equilibrium", **given)

def max_drawdown(prices=None):
    """Maximum drawdown. The largest fall from a running peak to a later trough, as a fraction of the peak.
    Formula: \\mathrm{MDD} = \\max_{t}\\left(1 - \\frac{P_t}{\\max_{s\\le t} P_s}\\right)
    Inputs:
        prices: price or portfolio value series in time order
    Outputs: max_drawdown (max over t of 1 - P_t / max_{s<=t} P_s)
    See also: help("max_drawdown")
    """
    given = {k: v for k, v in dict(prices=prices).items() if v is not None}
    return _P.solve("max_drawdown", **given)

def mean_returns(returns=None):
    """Arithmetic and geometric mean return. Arithmetic mean, geometric (compound) mean and cumulative return of a series of periodic returns.
    Formula: \\bar R_G = \\left[\\prod_{t=1}^{n}(1 + R_t)\\right]^{1/n} - 1
    Inputs:
        returns: periodic returns (decimals)
    Outputs: arithmetic_mean (sum R / n), geometric_mean ((prod (1 + R))^(1/n) - 1), cumulative_return (prod (1 + R) - 1)
    See also: help("mean_returns")
    """
    given = {k: v for k, v in dict(returns=returns).items() if v is not None}
    return _P.solve("mean_returns", **given)

def min_variance_two_asset(sd_1=None, sd_2=None, correlation=None):
    """Minimum-variance portfolio of two assets. The weights of two assets that minimise the portfolio variance (short sales allowed), and that variance's sd.
    Formula: w_1^{*} = \\frac{\\sigma_2^{2} - \\rho\\sigma_1\\sigma_2}{\\sigma_1^{2} + \\sigma_2^{2} - 2\\rho\\sigma_1\\sigma_2}
    Inputs:
        sd_1: standard deviation of asset 1 (decimal)
        sd_2: standard deviation of asset 2 (decimal)
        correlation: correlation between the assets (-1..1)
    Outputs: weight_1 (w1 = (s2^2 - rho s1 s2) / (s1^2 + s2^2 - 2 rho s1 s2)), weight_2 (1 - w1), std_dev (standard deviation of the minimum-variance portfolio)
    See also: help("min_variance_two_asset")
    """
    given = {k: v for k, v in dict(sd_1=sd_1, sd_2=sd_2, correlation=correlation).items() if v is not None}
    return _P.solve("min_variance_two_asset", **given)

def mirr(cash_flows=None, finance_rate=None, reinvest_rate=None):
    """Modified internal rate of return. MIRR: outflows discounted at the finance rate, inflows compounded to the end at the reinvestment rate.
    Formula: \\mathrm{MIRR} = \\left(\\frac{FV_{+}}{PV_{-}}\\right)^{1/n} - 1
    Inputs:
        cash_flows: cash flows [CF0, ..., CFn], CF0 at time 0
        finance_rate: finance rate for outflows (decimal)
        reinvest_rate: reinvestment rate for inflows (decimal)
    Outputs: mirr (modified IRR per period), terminal_value (inflows compounded to period n), pv_outflows (present value of the outflows)
    See also: help("mirr")
    """
    given = {k: v for k, v in dict(cash_flows=cash_flows, finance_rate=finance_rate, reinvest_rate=reinvest_rate).items() if v is not None}
    return _P.solve("mirr", **given)

def money_multiplier(reserve_ratio=None, currency_ratio=None, monetary_base=None):
    """Money multiplier. Simple deposit multiplier 1/rr and the money multiplier (1 + c)/(rr + c) with a currency-deposit ratio c, and the money supply from the monetary base.
    Formula: m = \\frac{1 + c}{rr + c}
    Inputs:
        reserve_ratio: reserve ratio (decimal)
        currency_ratio: currency-to-deposit ratio (default 0) (optional)
        monetary_base: monetary base (optional) (optional)
    Outputs: simple_multiplier (1/rr), money_multiplier ((1 + c)/(rr + c)), money_supply (multiplier x base)
    See also: help("money_multiplier")
    """
    given = {k: v for k, v in dict(reserve_ratio=reserve_ratio, currency_ratio=currency_ratio, monetary_base=monetary_base).items() if v is not None}
    return _P.solve("money_multiplier", **given)

def monopoly(price_intercept=None, price_slope=None, marginal_cost=None, fixed_cost=None, cost_quadratic=None):
    """Monopoly profit maximization. Profit-maximising quantity and price of a monopoly facing P = A - BQ with cost F + cQ + eQ^2, its profit, Lerner index and the deadweight loss against marginal-cost pricing.
    Formula: Q^{*} = \\frac{A - c}{2(B + e)},\\quad P^{*} = A - BQ^{*}
    Inputs:
        price_intercept: A in the inverse demand P = A - B Q
        price_slope: B in P = A - B Q (B > 0)
        marginal_cost: c, the constant part of marginal cost
        fixed_cost: fixed cost F (default 0) (optional)
        cost_quadratic: e in the cost F + cQ + eQ^2 (default 0) (optional)
    Outputs: quantity (Q* where MR = MC), price (A - B Q*), profit (P Q - cost), lerner_index ((P - MC)/P), deadweight_loss (loss against P = MC)
    See also: help("monopoly")
    """
    given = {k: v for k, v in dict(price_intercept=price_intercept, price_slope=price_slope, marginal_cost=marginal_cost, fixed_cost=fixed_cost, cost_quadratic=cost_quadratic).items() if v is not None}
    return _P.solve("monopoly", **given)

def multiple_regression(X=None, y=None):
    """Multiple linear regression (OLS). Least-squares coefficients of y = b0 + b1 x1 + ... + bk xk (intercept added), R^2 and adjusted R^2.
    Formula: \\hat\\beta = (X^{\\top}X)^{-1}X^{\\top}y
    Inputs:
        X: regressor matrix, one row per observation, one column per variable (no constant column)
        y: dependent variable, one value per row of X
    Outputs: coefficients ([b0 (intercept), b1, ..., bk]), r_squared (1 - SSR/SST), adj_r_squared (1 - (1 - R^2)(n - 1)/(n - k - 1))
    See also: help("multiple_regression")
    """
    given = {k: v for k, v in dict(X=X, y=y).items() if v is not None}
    return _P.solve("multiple_regression", **given)

def net_premium_whole_life(mortality_rates=None, interest_rate=None, benefit=None):
    """Net annual premium for whole life insurance. The level annual net premium, paid at the start of each year while alive, for a whole life benefit (equivalence principle): P = B A_x / a-due_x.
    Formula: P = B\\,\\frac{A_x}{\\ddot a_x}
    Inputs:
        mortality_rates: one-year death probabilities q_x, q_x+1, ... from the current age
        interest_rate: annual effective interest rate (decimal)
        benefit: benefit amount (default 1) (optional)
    Outputs: premium (net annual premium B A_x / a-due_x), insurance_apv (B A_x), annuity_due (a-due_x)
    See also: help("net_premium_whole_life")
    """
    given = {k: v for k, v in dict(mortality_rates=mortality_rates, interest_rate=interest_rate, benefit=benefit).items() if v is not None}
    return _P.solve("net_premium_whole_life", **given)

def nominal_rate(effective_rate=None, periods_per_year=None):
    """Nominal rate from an effective rate. The nominal annual rate (APR) compounded m times a year that gives a stated effective annual rate.
    Formula: r = m\\left[(1 + \\mathrm{EAR})^{1/m} - 1\\right]
    Inputs:
        effective_rate: effective annual rate (decimal)
        periods_per_year: compounding periods per year
    Outputs: nominal_rate (nominal annual rate m((1 + EAR)^(1/m) - 1)), periodic_rate (rate per period)
    See also: help("nominal_rate")
    """
    given = {k: v for k, v in dict(effective_rate=effective_rate, periods_per_year=periods_per_year).items() if v is not None}
    return _P.solve("nominal_rate", **given)

def npv(rate=None, cash_flows=None):
    """Net present value. NPV of cash flows [CF0, CF1, ..., CFn] (CF0 now, CFt at the end of period t) at a discount rate per period.
    Formula: NPV = \\sum_{t=0}^{n} \\frac{CF_t}{(1 + r)^{t}}
    Inputs:
        rate: discount rate per period (decimal)
        cash_flows: cash flows [CF0, CF1, ..., CFn], CF0 at time 0
    Outputs: npv (net present value)
    See also: help("npv")
    """
    given = {k: v for k, v in dict(rate=rate, cash_flows=cash_flows).items() if v is not None}
    return _P.solve("npv", **given)

def number_of_periods(present_value=None, payment=None, rate=None, timing=None):
    """Number of payments to repay a loan. How many periodic payments repay a present value at a rate per period (a fractional answer means the last payment is smaller).
    Formula: n = \\frac{-\\ln\\left(1 - \\frac{PV\\,r}{PMT}\\right)}{\\ln(1 + r)}
    Inputs:
        present_value: amount borrowed (present value)
        payment: payment per period
        rate: interest rate per period (decimal)
        timing: 'ordinary' (end of each period, default) or 'due' (beginning) (optional)
    Outputs: periods (number of periods n (may be fractional))
    See also: help("number_of_periods")
    """
    given = {k: v for k, v in dict(present_value=present_value, payment=payment, rate=rate, timing=timing).items() if v is not None}
    return _P.solve("number_of_periods", **given)

def ols_simple(x=None, y=None):
    """Simple linear regression (OLS). Ordinary least squares fit y = a + b x: slope, intercept, R^2 and the standard error of the slope.
    Formula: \\hat\\beta = \\frac{\\sum(x - \\bar x)(y - \\bar y)}{\\sum (x - \\bar x)^{2}},\\quad \\hat\\alpha = \\bar y - \\hat\\beta\\bar x
    Inputs:
        x: explanatory variable values
        y: dependent variable values
    Outputs: slope (b = S_xy / S_xx), intercept (a = mean y - b mean x), r_squared (1 - SSR/SST), slope_std_error (sqrt(SSR/(n - 2) / S_xx)), n (observations)
    See also: help("ols_simple")
    """
    given = {k: v for k, v in dict(x=x, y=y).items() if v is not None}
    return _P.solve("ols_simple", **given)

def parametric_var(mean=None, std_dev=None, confidence=None, horizon=None, portfolio_value=None):
    """Parametric (normal) value at risk and expected shortfall. VaR and CVaR of normally distributed returns with a mean and standard deviation per period, scaled to a horizon by mean x h and sd x sqrt(h).
    Formula: \\mathrm{VaR} = V(z_c\\,\\sigma\\sqrt{h} - \\mu h),\\quad \\mathrm{ES} = V\\left(\\frac{\\sigma\\sqrt{h}\\,\\varphi(z_c)}{1 - c} - \\mu h\\right)
    Inputs:
        mean: mean return per period (decimal)
        std_dev: standard deviation of returns per period (decimal)
        confidence: confidence level (0.95 = 95%)
        horizon: horizon in periods (default 1) (optional)
        portfolio_value: portfolio value (default 1) (optional)
    Outputs: var (value at risk V (z sd sqrt(h) - mean h)), cvar (expected shortfall V (sd sqrt(h) phi(z)/(1 - c) - mean h)), z (standard normal quantile at the confidence level)
    See also: help("parametric_var")
    """
    given = {k: v for k, v in dict(mean=mean, std_dev=std_dev, confidence=confidence, horizon=horizon, portfolio_value=portfolio_value).items() if v is not None}
    return _P.solve("parametric_var", **given)

def payback_period(cash_flows=None):
    """Payback period. Time until the cumulative cash flow turns non-negative, interpolating linearly within the period (cash arriving evenly during the period).
    Formula: \\text{payback} = (t-1) + \\frac{-\\sum_{s<t} CF_s}{CF_t}
    Inputs:
        cash_flows: cash flows [CF0 < 0, CF1, ..., CFn > 0]
    Outputs: payback (payback period in periods)
    See also: help("payback_period")
    """
    given = {k: v for k, v in dict(cash_flows=cash_flows).items() if v is not None}
    return _P.solve("payback_period", **given)

def per_unit_tax(demand_intercept=None, demand_slope=None, supply_intercept=None, supply_slope=None, tax=None):
    """Per-unit tax incidence (linear curves). Effect of a per-unit tax on Qd = a - bP, Qs = c + dP: quantity, price paid by buyers and kept by sellers, tax revenue, deadweight loss and the buyers' share of the burden.
    Formula: P_b = \\frac{a - c + d\\,t}{b + d},\\quad DWL = \\tfrac12\\,t\\,(Q_0 - Q_t)
    Inputs:
        demand_intercept: a in Qd = a - bP
        demand_slope: b in Qd = a - bP (b > 0)
        supply_intercept: c in Qs = c + dP
        supply_slope: d in Qs = c + dP (d > 0)
        tax: tax per unit
    Outputs: quantity (quantity with the tax), buyer_price (price paid by buyers), seller_price (buyer price - tax), tax_revenue (t Q), deadweight_loss (t (Q0 - Qt) / 2), buyer_share (share of the tax borne by buyers d/(b+d))
    See also: help("per_unit_tax")
    """
    given = {k: v for k, v in dict(demand_intercept=demand_intercept, demand_slope=demand_slope, supply_intercept=supply_intercept, supply_slope=supply_slope, tax=tax).items() if v is not None}
    return _P.solve("per_unit_tax", **given)

def perpetuity(payment=None, rate=None, timing=None):
    """Present value of a perpetuity. The value today of an equal payment every period forever: PV = C / r (C / r + C if payments start now).
    Formula: PV = \\frac{C}{r}
    Inputs:
        payment: payment per period
        rate: discount rate per period (decimal)
        timing: 'ordinary' (first payment in one period, default) or 'due' (first payment now) (optional)
    Outputs: present_value (value today)
    See also: help("perpetuity")
    """
    given = {k: v for k, v in dict(payment=payment, rate=rate, timing=timing).items() if v is not None}
    return _P.solve("perpetuity", **given)

def point_elasticity(demand_intercept=None, demand_slope=None, price=None):
    """Point elasticity of a linear demand curve. Quantity, point price elasticity and revenue on the linear demand curve Q = a - b P at a price, and the revenue-maximising price.
    Formula: E = \\frac{dQ}{dP}\\frac{P}{Q} = \\frac{-bP}{a - bP}
    Inputs:
        demand_intercept: a in Q = a - bP
        demand_slope: b in Q = a - bP (b > 0)
        price: price at which to evaluate
    Outputs: quantity (Q = a - bP), elasticity (-b P / Q), revenue (P Q), revenue_maximizing_price (a / (2b))
    See also: help("point_elasticity")
    """
    given = {k: v for k, v in dict(demand_intercept=demand_intercept, demand_slope=demand_slope, price=price).items() if v is not None}
    return _P.solve("point_elasticity", **given)

def portfolio_return_risk(weights=None, expected_returns=None, covariance=None):
    """Portfolio expected return and risk. Expected return w'mu, variance w'Sigma w and standard deviation of a portfolio from its weights, expected returns and covariance matrix.
    Formula: E[R_p] = w^{\\top}\\mu,\\quad \\sigma_p^{2} = w^{\\top}\\Sigma\\,w
    Inputs:
        weights: portfolio weights, adding up to 1 (negative = short)
        expected_returns: expected return of each asset (decimals)
        covariance: covariance matrix of the returns [[s11, s12], [s21, s22]]
    Outputs: expected_return (w' mu), variance (w' Sigma w), std_dev (sqrt(variance))
    See also: help("portfolio_return_risk")
    """
    given = {k: v for k, v in dict(weights=weights, expected_returns=expected_returns, covariance=covariance).items() if v is not None}
    return _P.solve("portfolio_return_risk", **given)

def portfolio_var(weights=None, covariance=None, confidence=None, portfolio_value=None, horizon=None):
    """Portfolio value at risk (variance-covariance). Zero-mean normal VaR of a portfolio from its weights and the covariance matrix of periodic returns, with the undiversified VaR (sum of the assets' own VaRs) and the diversification benefit.
    Formula: \\mathrm{VaR} = z_c\\sqrt{w^{\\top}\\Sigma w}\\,\\sqrt{h}\\,V
    Inputs:
        weights: portfolio weights (fractions of the portfolio value)
        covariance: covariance matrix of periodic returns
        confidence: confidence level (0.99 = 99%)
        portfolio_value: portfolio value (default 1) (optional)
        horizon: horizon in periods (default 1) (optional)
    Outputs: var (z sqrt(w'Sigma w) sqrt(h) V), portfolio_sd (sqrt(w'Sigma w) per period), undiversified_var (z sqrt(h) V sum |w_i| sigma_i), diversification_benefit (undiversified - portfolio VaR)
    See also: help("portfolio_var")
    """
    given = {k: v for k, v in dict(weights=weights, covariance=covariance, confidence=confidence, portfolio_value=portfolio_value, horizon=horizon).items() if v is not None}
    return _P.solve("portfolio_var", **given)

def present_value(future_value=None, rate=None, periods=None):
    """Present value of a single sum. What a single amount received after n periods is worth today at a rate per period: PV = FV / (1 + r)^n.
    Formula: PV = \\frac{FV}{(1 + r)^{n}}
    Inputs:
        future_value: amount received in the future
        rate: discount rate per period (decimal)
        periods: number of periods until the amount is received
    Outputs: present_value (value today FV (1 + r)^-n), discount_factor ((1 + r)^-n)
    See also: help("present_value")
    """
    given = {k: v for k, v in dict(future_value=future_value, rate=rate, periods=periods).items() if v is not None}
    return _P.solve("present_value", **given)

def present_value_annuity(payment=None, rate=None, periods=None, timing=None):
    """Present value of an annuity. The value today of n equal payments, ordinary (end of period) or due (beginning).
    Formula: PV = PMT\\,\\frac{1 - (1+r)^{-n}}{r}\\;(\\times (1 + r)\\ \\text{if due})
    Inputs:
        payment: payment per period
        rate: interest rate per period (decimal)
        periods: number of payments
        timing: 'ordinary' (end of each period, default) or 'due' (beginning) (optional)
    Outputs: present_value (value today of the payments)
    See also: help("present_value_annuity")
    """
    given = {k: v for k, v in dict(payment=payment, rate=rate, periods=periods, timing=timing).items() if v is not None}
    return _P.solve("present_value_annuity", **given)

def price_indices(base_prices=None, base_quantities=None, current_prices=None, current_quantities=None):
    """Laspeyres, Paasche and Fisher price indices. Price indices (base = 100) of a basket: Laspeyres (base-year quantities, the CPI method), Paasche (current quantities) and Fisher (their geometric mean).
    Formula: L = 100\\frac{\\sum p_1 q_0}{\\sum p_0 q_0},\\quad P = 100\\frac{\\sum p_1 q_1}{\\sum p_0 q_1},\\quad F = \\sqrt{LP}
    Inputs:
        base_prices: prices in the base year
        base_quantities: quantities in the base year
        current_prices: prices in the current year
        current_quantities: quantities in the current year
    Outputs: laspeyres (100 sum p1 q0 / sum p0 q0), paasche (100 sum p1 q1 / sum p0 q1), fisher (sqrt(L P))
    See also: help("price_indices")
    """
    given = {k: v for k, v in dict(base_prices=base_prices, base_quantities=base_quantities, current_prices=current_prices, current_quantities=current_quantities).items() if v is not None}
    return _P.solve("price_indices", **given)

def profitability_index(rate=None, cash_flows=None):
    """Profitability index. PV of the future cash flows divided by the initial investment (benefit-cost ratio).
    Formula: PI = \\frac{\\sum_{t=1}^{n} CF_t (1+r)^{-t}}{-CF_0}
    Inputs:
        rate: discount rate per period (decimal)
        cash_flows: cash flows [CF0 < 0, CF1, ..., CFn]
    Outputs: profitability_index (PV(CF1..CFn) / |CF0|), pv_future (PV of CF1..CFn), npv (net present value)
    See also: help("profitability_index")
    """
    given = {k: v for k, v in dict(rate=rate, cash_flows=cash_flows).items() if v is not None}
    return _P.solve("profitability_index", **given)

def put_call_parity(call_price=None, spot=None, strike=None, time=None, rate=None, dividend_yield=None):
    """Put-call parity. The price of a European put from the call with the same strike and expiry: P = C - S e^(-qT) + K e^(-rT).
    Formula: C + K e^{-rT} = P + S e^{-qT}
    Inputs:
        call_price: price of the European call
        spot: price of the underlying now
        strike: strike (exercise) price
        time: time to expiry in years
        rate: risk-free rate, continuously compounded (decimal)
        dividend_yield: continuous dividend yield (decimal, default 0) (optional)
    Outputs: put_price (European put price), pv_strike (K e^(-rT)), pv_spot (S e^(-qT))
    See also: help("put_call_parity")
    """
    given = {k: v for k, v in dict(call_price=call_price, spot=spot, strike=strike, time=time, rate=rate, dividend_yield=dividend_yield).items() if v is not None}
    return _P.solve("put_call_parity", **given)

def scenario_return(probabilities=None, returns=None):
    """Expected return and risk from scenarios. Expected return, variance and standard deviation of an asset whose return depends on scenarios with given probabilities.
    Formula: E[R] = \\sum_i p_i R_i,\\quad \\sigma^{2} = \\sum_i p_i (R_i - E[R])^{2}
    Inputs:
        probabilities: probability of each scenario (adding up to 1)
        returns: return in each scenario (decimals)
    Outputs: expected_return (sum p R), variance (sum p (R - E)^2), std_dev (sqrt(variance))
    See also: help("scenario_return")
    """
    given = {k: v for k, v in dict(probabilities=probabilities, returns=returns).items() if v is not None}
    return _P.solve("scenario_return", **given)

def sharpe_ratio(returns=None, risk_free=None, periods_per_year=None):
    """Sharpe ratio. Mean excess return per unit of total risk, from a return series (sample standard deviation, n - 1); annualized by sqrt(periods per year).
    Formula: S = \\frac{\\bar R - r_f}{s_R}
    Inputs:
        returns: periodic returns (decimals)
        risk_free: risk-free rate per period (decimal, default 0) (optional)
        periods_per_year: periods per year for annualizing (12 monthly, 252 daily; default 1) (optional)
    Outputs: sharpe ((mean - rf) / sd per period), annualized_sharpe (sharpe x sqrt(periods per year)), mean_excess_return (mean - rf), std_dev (sample standard deviation)
    See also: help("sharpe_ratio")
    """
    given = {k: v for k, v in dict(returns=returns, risk_free=risk_free, periods_per_year=periods_per_year).items() if v is not None}
    return _P.solve("sharpe_ratio", **given)

def simple_interest(principal=None, rate=None, years=None):
    """Simple interest. Interest and final amount when interest is earned on the principal only: I = P r t.
    Formula: I = P\\,r\\,t,\\quad A = P(1 + r t)
    Inputs:
        principal: amount invested or borrowed
        rate: annual simple interest rate (decimal; 5% = 0.05)
        years: time in years
    Outputs: interest (simple interest earned P r t), amount (principal plus interest)
    See also: help("simple_interest")
    """
    given = {k: v for k, v in dict(principal=principal, rate=rate, years=years).items() if v is not None}
    return _P.solve("simple_interest", **given)

def sinking_fund(future_value=None, rate=None, periods=None, timing=None):
    """Sinking fund payment. The equal payment per period that accumulates to a target amount after n periods.
    Formula: PMT = \\frac{FV\\,r}{(1 + r)^{n} - 1}
    Inputs:
        future_value: target amount
        rate: interest rate per period (decimal)
        periods: number of payments
        timing: 'ordinary' (end of each period, default) or 'due' (beginning) (optional)
    Outputs: payment (payment per period)
    See also: help("sinking_fund")
    """
    given = {k: v for k, v in dict(future_value=future_value, rate=rate, periods=periods, timing=timing).items() if v is not None}
    return _P.solve("sinking_fund", **given)

def solow_steady_state(saving_rate=None, population_growth=None, depreciation=None, alpha=None, technology_growth=None, productivity=None):
    """Solow model steady state. Steady-state capital, output and consumption per effective worker in the Solow model with y = A k^alpha, and the golden-rule saving rate and capital.
    Formula: k^{*} = \\left(\\frac{sA}{n + g + \\delta}\\right)^{\\frac{1}{1-\\alpha}}
    Inputs:
        saving_rate: saving rate s (decimal)
        population_growth: population growth n (decimal)
        depreciation: depreciation rate (decimal)
        alpha: capital share alpha in y = A k^alpha
        technology_growth: technology growth g (default 0) (optional)
        productivity: total factor productivity A (default 1) (optional)
    Outputs: capital (k* = (sA/(n + g + delta))^(1/(1 - alpha))), output (y* = A k*^alpha), consumption ((1 - s) y*), golden_rule_saving (alpha), golden_rule_capital ((alpha A/(n + g + delta))^(1/(1 - alpha)))
    See also: help("solow_steady_state")
    """
    given = {k: v for k, v in dict(saving_rate=saving_rate, population_growth=population_growth, depreciation=depreciation, alpha=alpha, technology_growth=technology_growth, productivity=productivity).items() if v is not None}
    return _P.solve("solow_steady_state", **given)

def sortino_ratio(returns=None, target=None):
    """Sortino ratio. Mean return above a target per unit of downside deviation sqrt(mean(min(0, R - T)^2)) over ALL observations.
    Formula: \\mathrm{Sortino} = \\frac{\\bar R - T}{\\sqrt{\\frac{1}{n}\\sum_i \\min(0, R_i - T)^{2}}}
    Inputs:
        returns: periodic returns (decimals)
        target: target (minimum acceptable) return per period (default 0) (optional)
    Outputs: sortino ((mean - T) / downside deviation), downside_deviation (sqrt(sum min(0, R - T)^2 / n)), mean_return (mean return)
    See also: help("sortino_ratio")
    """
    given = {k: v for k, v in dict(returns=returns, target=target).items() if v is not None}
    return _P.solve("sortino_ratio", **given)

def spending_multiplier(mpc=None, tax_rate=None, import_propensity=None, spending_change=None):
    """Keynesian spending multiplier. Government-spending multiplier 1/(1 - mpc(1 - t) + m), the lump-sum tax multiplier and the change in output from a change in spending.
    Formula: k = \\frac{1}{1 - c(1 - t) + m}
    Inputs:
        mpc: marginal propensity to consume
        tax_rate: proportional income tax rate (default 0) (optional)
        import_propensity: marginal propensity to import (default 0) (optional)
        spending_change: change in government spending (optional) (optional)
    Outputs: spending_multiplier (1/(1 - mpc(1 - t) + m)), tax_multiplier (-mpc x multiplier), output_change (multiplier x spending change)
    See also: help("spending_multiplier")
    """
    given = {k: v for k, v in dict(mpc=mpc, tax_rate=tax_rate, import_propensity=import_propensity, spending_change=spending_change).items() if v is not None}
    return _P.solve("spending_multiplier", **given)

def stackelberg(price_intercept=None, price_slope=None, cost_leader=None, cost_follower=None):
    """Stackelberg duopoly equilibrium. Quantities, price and profits when a leader chooses its quantity first and the follower best-responds, against P = A - B(qL + qF) with constant marginal costs.
    Formula: q_L^{*} = \\frac{A - 2c_L + c_F}{2B},\\quad q_F^{*} = \\frac{A - c_F - Bq_L^{*}}{2B}
    Inputs:
        price_intercept: A in the inverse demand P = A - B Q
        price_slope: B in P = A - B Q (B > 0)
        cost_leader: marginal cost of the leader
        cost_follower: marginal cost of the follower
    Outputs: q_leader ((A - 2cL + cF)/(2B)), q_follower ((A - cF - B qL)/(2B)), price (market price), profit_leader (leader's profit), profit_follower (follower's profit)
    See also: help("stackelberg")
    """
    given = {k: v for k, v in dict(price_intercept=price_intercept, price_slope=price_slope, cost_leader=cost_leader, cost_follower=cost_follower).items() if v is not None}
    return _P.solve("stackelberg", **given)

def survival_probability(mortality_rates=None, years=None, deferred_years=None):
    """Survival and death probabilities from a life table. t p_x (survive t years), t q_x (die within t years) and t|u q_x (survive t years, then die within the next u years) from one-year mortality rates.
    Formula: {}_{t}p_x = \\prod_{k=0}^{t-1}(1 - q_{x+k}),\\quad {}_{t|u}q_x = {}_{t}p_x - {}_{t+u}p_x
    Inputs:
        mortality_rates: one-year death probabilities q_x, q_x+1, ... from the current age
        years: number of years t
        deferred_years: u, the length of the death window after t (default 1) (optional)
    Outputs: survival (t p_x = prod (1 - q)), death_probability (t q_x = 1 - t p_x), deferred_death_probability (t|u q_x = t p_x - (t+u) p_x)
    See also: help("survival_probability")
    """
    given = {k: v for k, v in dict(mortality_rates=mortality_rates, years=years, deferred_years=deferred_years).items() if v is not None}
    return _P.solve("survival_probability", **given)

def tangency_portfolio(expected_returns=None, covariance=None, risk_free=None):
    """Tangency (maximum Sharpe ratio) portfolio. Weights of the risky portfolio with the highest Sharpe ratio (short sales allowed): w proportional to Sigma^-1 (mu - rf).
    Formula: w^{*} = \\frac{\\Sigma^{-1}(\\mu - r_f\\mathbf{1})}{\\mathbf{1}^{\\top}\\Sigma^{-1}(\\mu - r_f\\mathbf{1})}
    Inputs:
        expected_returns: expected returns of the assets (decimals)
        covariance: covariance matrix of the returns
        risk_free: risk-free rate (decimal)
    Outputs: weights (tangency weights (list, add up to 1)), expected_return (portfolio expected return), std_dev (portfolio sd), sharpe ((E - rf) / sd)
    See also: help("tangency_portfolio")
    """
    given = {k: v for k, v in dict(expected_returns=expected_returns, covariance=covariance, risk_free=risk_free).items() if v is not None}
    return _P.solve("tangency_portfolio", **given)

def temporary_annuity_due(mortality_rates=None, interest_rate=None, term=None, payment=None):
    """Temporary life annuity-due. Actuarial present value of up to n annual payments at the start of each year while alive.
    Formula: \\ddot a_{x:\\overline{n}|} = \\sum_{k=0}^{n-1} v^{k}\\,{}_{k}p_x
    Inputs:
        mortality_rates: one-year death probabilities q_x, q_x+1, ... from the current age
        interest_rate: annual effective interest rate (decimal)
        term: term n in years
        payment: annual payment (default 1) (optional)
    Outputs: apv (P sum_{k<n} v^k k p_x)
    See also: help("temporary_annuity_due")
    """
    given = {k: v for k, v in dict(mortality_rates=mortality_rates, interest_rate=interest_rate, term=term, payment=payment).items() if v is not None}
    return _P.solve("temporary_annuity_due", **given)

def term_insurance(mortality_rates=None, interest_rate=None, term=None, benefit=None):
    """Term life insurance (net single premium). Actuarial present value of a benefit paid at the end of the year of death if death occurs within n years.
    Formula: A^{1}_{x:\\overline{n}|} = \\sum_{k=0}^{n-1} v^{k+1}\\,{}_{k}p_x\\,q_{x+k}
    Inputs:
        mortality_rates: one-year death probabilities q_x, q_x+1, ... from the current age
        interest_rate: annual effective interest rate (decimal)
        term: term n in years
        benefit: benefit amount (default 1) (optional)
    Outputs: apv (B A^1_{x:n} = B sum_{k<n} v^(k+1) k p_x q_x+k)
    See also: help("term_insurance")
    """
    given = {k: v for k, v in dict(mortality_rates=mortality_rates, interest_rate=interest_rate, term=term, benefit=benefit).items() if v is not None}
    return _P.solve("term_insurance", **given)

def treynor_jensen(portfolio_returns=None, market_returns=None, risk_free=None):
    """Treynor ratio and Jensen's alpha. Excess return per unit of beta (Treynor) and the return above the CAPM prediction (Jensen's alpha), from paired portfolio and market returns and a constant risk-free rate per period.
    Formula: T = \\frac{\\bar R_p - r_f}{\\beta_p},\\quad \\alpha_J = \\bar R_p - [r_f + \\beta_p(\\bar R_m - r_f)]
    Inputs:
        portfolio_returns: portfolio returns (decimals) per period
        market_returns: market returns in the same periods
        risk_free: risk-free rate per period (decimal, default 0) (optional)
    Outputs: beta (beta of the portfolio), treynor ((mean Rp - rf) / beta), jensen_alpha (mean Rp - [rf + beta (mean Rm - rf)]), mean_portfolio_return (mean Rp), mean_market_return (mean Rm)
    See also: help("treynor_jensen")
    """
    given = {k: v for k, v in dict(portfolio_returns=portfolio_returns, market_returns=market_returns, risk_free=risk_free).items() if v is not None}
    return _P.solve("treynor_jensen", **given)

def two_asset_portfolio(weight_1=None, return_1=None, return_2=None, sd_1=None, sd_2=None, correlation=None):
    """Two-asset portfolio return and risk. Expected return and standard deviation of a portfolio of two assets from the weight, means, standard deviations and correlation.
    Formula: \\sigma_p^{2} = w_1^{2}\\sigma_1^{2} + w_2^{2}\\sigma_2^{2} + 2 w_1 w_2 \\rho\\,\\sigma_1\\sigma_2
    Inputs:
        weight_1: weight of asset 1 (asset 2 gets 1 - w1)
        return_1: expected return of asset 1 (decimal)
        return_2: expected return of asset 2 (decimal)
        sd_1: standard deviation of asset 1 (decimal)
        sd_2: standard deviation of asset 2 (decimal)
        correlation: correlation between the two assets (-1..1)
    Outputs: expected_return (w1 r1 + w2 r2), std_dev (portfolio standard deviation), variance (portfolio variance), weight_2 (1 - w1)
    See also: help("two_asset_portfolio")
    """
    given = {k: v for k, v in dict(weight_1=weight_1, return_1=return_1, return_2=return_2, sd_1=sd_1, sd_2=sd_2, correlation=correlation).items() if v is not None}
    return _P.solve("two_asset_portfolio", **given)

def two_stage_ddm(dividend=None, high_growth=None, high_growth_years=None, stable_growth=None, required_return=None):
    """Two-stage dividend discount model. Share value when dividends grow at a high rate for n years and at a stable rate forever after.
    Formula: P_0 = \\sum_{k=1}^{n} \\frac{D_0(1+g_1)^{k}}{(1+r)^{k}} + \\frac{D_{n}(1+g_2)}{(r - g_2)(1+r)^{n}}
    Inputs:
        dividend: dividend just paid D0
        high_growth: growth rate in the first stage (decimal)
        high_growth_years: number of years of high growth
        stable_growth: growth rate forever after (decimal)
        required_return: required return on equity (decimal)
    Outputs: price (share value), terminal_value (value at year n of the dividends after n), pv_terminal (present value of the terminal value), pv_high_growth_dividends (present value of D1..Dn)
    See also: help("two_stage_ddm")
    """
    given = {k: v for k, v in dict(dividend=dividend, high_growth=high_growth, high_growth_years=high_growth_years, stable_growth=stable_growth, required_return=required_return).items() if v is not None}
    return _P.solve("two_stage_ddm", **given)

def wacc(equity_value=None, debt_value=None, cost_of_equity=None, cost_of_debt=None, tax_rate=None):
    """Weighted average cost of capital. WACC = E/V re + D/V rd (1 - t): the after-tax cost of a firm's capital at market-value weights.
    Formula: \\mathrm{WACC} = \\frac{E}{V} r_e + \\frac{D}{V} r_d (1 - t)
    Inputs:
        equity_value: market value of equity
        debt_value: market value of debt
        cost_of_equity: cost of equity (decimal)
        cost_of_debt: pre-tax cost of debt (decimal)
        tax_rate: corporate tax rate (decimal)
    Outputs: wacc (weighted average cost of capital), after_tax_cost_of_debt (rd (1 - t)), equity_weight (E / V), debt_weight (D / V)
    See also: help("wacc")
    """
    given = {k: v for k, v in dict(equity_value=equity_value, debt_value=debt_value, cost_of_equity=cost_of_equity, cost_of_debt=cost_of_debt, tax_rate=tax_rate).items() if v is not None}
    return _P.solve("wacc", **given)

def whole_life_insurance(mortality_rates=None, interest_rate=None, benefit=None):
    """Whole life insurance (net single premium). Actuarial present value A_x of a benefit paid at the end of the year of death, whenever it occurs.
    Formula: A_x = \\sum_{k=0}^{\\infty} v^{k+1}\\,{}_{k}p_x\\,q_{x+k}
    Inputs:
        mortality_rates: one-year death probabilities q_x, q_x+1, ... from the current age
        interest_rate: annual effective interest rate (decimal)
        benefit: benefit amount (default 1) (optional)
    Outputs: apv (B A_x = B sum v^(k+1) k p_x q_x+k)
    See also: help("whole_life_insurance")
    """
    given = {k: v for k, v in dict(mortality_rates=mortality_rates, interest_rate=interest_rate, benefit=benefit).items() if v is not None}
    return _P.solve("whole_life_insurance", **given)

def zero_coupon_bond(face=None, ytm=None, years=None, compounding=None):
    """Price of a zero-coupon bond. Price of a bond that pays only its face value at maturity, at a yield with a stated compounding.
    Formula: P = \\frac{F}{(1 + y/m)^{m t}}
    Inputs:
        face: face value paid at maturity
        ytm: yield (decimal), with the stated compounding
        years: years to maturity
        compounding: annual (default), semiannual, quarterly, monthly or continuous (optional)
    Outputs: price (price F x discount factor), discount_factor ((1 + y/m)^(-m t) or e^(-y t))
    See also: help("zero_coupon_bond")
    """
    given = {k: v for k, v in dict(face=face, ytm=ytm, years=years, compounding=compounding).items() if v is not None}
    return _P.solve("zero_coupon_bond", **given)


